```html
<!doctype html>
<html lang="en"><head><meta charset="UTF-8" />
<meta name="viewport" content="width=1080, height=1920" />
<script src="hairline-kit.js"></script>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { width: 1080px; height: 1920px; overflow: hidden; background: #0e0f12; }
  #root { position: relative; width: 100%; height: 100%; background: var(--plate);
          --plate: #0e0f12; --hi: #fafafa; --edge: #a1a1aa; --mid: #52525b; --lo: #27272a; --stroke: 2.2px; }
  #art { position: absolute; inset: 0; }
  .hl-sil { fill: var(--plate); stroke: var(--edge); stroke-width: var(--stroke); stroke-linejoin: round; }
  .hl-sil.hi { stroke: var(--hi); }
  .hl-crease { fill: none; stroke: var(--mid); stroke-width: var(--stroke); stroke-linecap: round; }
  .hl-guide { fill: none; stroke: var(--lo); stroke-width: var(--stroke); stroke-dasharray: 6 10; }
</style></head>
<body>
<div id="root" data-composition-id="main" data-start="0" data-duration="8" data-width="1080" data-height="1920">
  <svg id="art" viewBox="0 0 1080 1920" role="img" aria-label="Isometric line drawing of a four-drawer cabinet; the drawers slide out one after another"></svg>
</div>
<script>
const D = 8;
const { el, frame, solid, put, springAt, tourAt } = HairlineKit;
const svg = document.getElementById('art');
const K = frame(520, 1100, 1.9);
const W = 240, DEP = 200, DH = 88, PITCH = 94, BASE = 24, OUT = 90;

// Tour: drawers are numbered from the top (0) down; they open in turn, then close, bottom first.
const TOUR = [{ t: 0, at: null }, { t: 0.9, at: 0 }, { t: 2.0, at: 1 }, { t: 3.1, at: 2 }, { t: 4.2, at: 3 }, { t: 5.8, at: null }];
const openT = [0.9, 2.0, 3.1, 4.2], closeT = [6.4, 6.2, 6.0, 5.8];   // reverse order, 0.2 s apart

// Back to front, lower z first. Carcass, plinth and top cap are static.
put(svg, solid(K.P, { x: 0, y: 0, w: W, d: DEP, z: BASE, h: 4 * PITCH + 4, r: 8 }));
put(svg, solid(K.P, { x: -6, y: -6, w: W + 12, d: DEP + 12, z: 0, h: BASE, r: 10 }));
put(svg, solid(K.P, { x: -8, y: -8, w: W + 16, d: DEP + 16, z: BASE + 4 * PITCH + 4, h: 14, r: 10 }));
const drawers = [];
for (let level = 0; level < 4; level++) {                 // level 0 = bottom, drawn first
  const s = 3 - level, g = el('g', {}, svg);
  drawers.push({ s, z: BASE + 4 + level * PITCH, box: put(g, { sil: '', crease: '' }), handle: put(g, { sil: '', crease: '' }),
    changes: [{ t: openT[s], to: OUT }, { t: closeT[s], to: 0 }] });
}

function renderFrame(t) {
  const at = tourAt(t, TOUR);
  for (const d of drawers) {
    const out = springAt(t, 0, d.changes);                // a position: spring, small overshoot
    d.box.draw(solid(K.P, { x: 6, y: out, w: W - 12, d: DEP, z: d.z, h: DH, r: 6, inset: 3 }));
    d.handle.draw(solid(K.P, { x: W / 2 - 30, y: DEP + out, w: 60, d: 10, z: d.z + DH / 2 - 4, h: 8, r: 4, inset: 1.5 }));
    const hi = at === null ? d.s === 0 : d.s === at;      // exactly one bright place: rest mark, or the newest drawer
    d.box.sil.classList.toggle('hi', hi && at !== null);
    d.handle.sil.classList.toggle('hi', hi);
  }
}
window.renderFrame = renderFrame;
renderFrame(0);
</script></body></html>
```

